/**
 * Typed wrappers around the Wails-generated bindings.
 *
 * The generated bindings are plain JavaScript with JSDoc types. This
 * module re-exports them behind a stable, strongly typed surface so the
 * React components never import generated files directly.
 *
 * The bindings are regenerated by `wails3 generate bindings` and are not
 * checked in.
 */

import * as AppServiceBindings from '../../bindings/github.com/incurl/wikirevele/internal/bindings/appservice';
import * as BindingsModels from '../../bindings/github.com/incurl/wikirevele/internal/bindings/models';
import * as JobsModels from '../../bindings/github.com/incurl/wikirevele/internal/jobs/models';
import * as ConsoleModels from '../../bindings/github.com/incurl/wikirevele/internal/console/models';
import * as WikidataModels from '../../bindings/github.com/incurl/wikirevele/internal/bindings/models';
import * as WikidataPackage from '../../bindings/github.com/incurl/wikirevele/internal/wikidata/models';

// The generated model classes are the source of truth for the shapes that
// cross the Wails boundary. The status and kind fields are narrowed to
// literal unions here, at the single point where the raw generated types
// enter the application.
export type Job = JobsModels.Job & {
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';
  // The bindings are generated as interfaces, where a missing array is
  // typed as nullable. The backend always sends an array, so it is
  // normalised here.
  artifact_ids: string[];
  input_artifact_ids: string[];
  params: Record<string, unknown>;
  result: Record<string, unknown>;
};
export type Artifact = JobsModels.Artifact & {
  kind: 'input' | 'output';
  meta: Record<string, unknown>;
};
export type ConsoleEntry = ConsoleModels.Entry;

/**
 * The imported Wikidata items the panel browses.
 *
 * The items are the records of the database, where the importer put
 * them. The claims are the statements of the dataset, typed as a
 * record of unknown: the panel's own types describe the shape it
 * expects, and the backend does not have to mirror it.
 */
export type WikidataItems = {
  items: WikidataModels.WikidataItemView[];
  total: number;
  properties: Record<string, string>;
};

/**
 * The application settings as seen by the UI.
 *
 * The API key is never returned by the backend, only its presence.
 */
export type Settings = BindingsModels.SettingsView;

/**
 * The parameters of an ETL pipeline run.
 *
 * The languages are normalised here: the generator types a missing
 * array as nullable, and the backend always sends an array.
 */
/**
 * The parameters of an ETL pipeline run.
 *
 * The arrays are normalised here: the generator types a missing array
 * as nullable, and the backend always sends an array.
 */
export type EtlJobOptions = Omit<
  BindingsModels.EtlJobOptions,
  'langs' | 'target_qids' | 'target_labels' | 'out_items_paths'
> & {
  langs: string[];
  target_qids: string[];
  target_labels: string[];
  out_items_paths: string[];
};

/**
 * The state of an ETL pipeline run.
 */
export type EtlProgress = Omit<BindingsModels.EtlProgress, 'item_files'> & {
  item_files: string[];
};

/**
 * One run of the ETL worker, as the history shows it.
 *
 * The targets and the item files are normalised here: the generator
 * types a missing array as nullable, and the backend always sends an
 * array.
 */
export type EtlHistoryEntry = Omit<
  BindingsModels.EtlHistoryEntry,
  'target_qids' | 'out_items_paths'
> & {
  target_qids: string[];
  out_items_paths: string[];
};

/**
 * The Wails event name emitted when a job changes state.
 */
export const EVENT_JOB_UPDATED = 'job:updated';

/**
 * The Wails event name emitted when a debug console entry is added.
 */
export const EVENT_CONSOLE_ENTRY = 'console:entry';

/**
 * The Wails event name emitted when an ETL run changes state.
 */
export const EVENT_ETL_PROGRESS = 'etl:progress';

/**
 * The Wails event name emitted when a sync changes state.
 */
export const EVENT_SYNC_PROGRESS = 'sync:progress';

/**
 * The directions a collection can be synced in.
 *
 * The names are the ones the backend stores, and a rename on either
 * side would make a stored set unreadable.
 */
export const SYNC_DIRECTIONS = ['push', 'pull', 'reconcile'] as const;

/**
 * One direction of a sync.
 */
export type SyncDirection = (typeof SYNC_DIRECTIONS)[number];

/**
 * One collection that can be synced.
 *
 * The collections are normalised here: the generator types a missing
 * array as nullable, and the backend always sends an array.
 */
export type SyncCollection = Omit<BindingsModels.SyncCollectionView, 'direction'> & {
  direction: SyncDirection;
};

/**
 * The set of the collections that take part in a sync.
 */
export type SyncSet = Omit<BindingsModels.SyncSetView, 'collections'> & {
  collections: SyncCollection[];
};

/**
 * The progress of a sync.
 */
export type SyncProgress = BindingsModels.SyncProgressView;

/**
 * Submits a job.
 */
export function submitJob(request: {
  title?: string;
  prompt: string;
  params?: Record<string, unknown>;
  input_artifact_ids?: string[];
}): Promise<Job> {
  return AppServiceBindings.SubmitJob(request as never) as unknown as Promise<Job>;
}

/**
 * Cancels a pending or running job.
 */
export function cancelJob(jobId: string): Promise<void> {
  return AppServiceBindings.CancelJob(jobId) as Promise<void>;
}

/**
 * Removes a finished job from the queue.
 */
export function deleteJob(jobId: string): Promise<void> {
  return AppServiceBindings.DeleteJob(jobId) as Promise<void>;
}

/**
 * Re-runs a job with the same parameters.
 */
export function retryJob(jobId: string): Promise<Job> {
  return AppServiceBindings.RetryJob(jobId) as unknown as Promise<Job>;
}

/**
 * Lists the recorded jobs.
 */
export function listJobs(limit = 50): Promise<Job[]> {
  return AppServiceBindings.ListJobs(limit) as unknown as Promise<Job[]>;
}

/**
 * Lists the stored artifacts.
 *
 * An empty jobId lists every artifact.
 *
 * No panel calls this yet: the application has no artifact panel. It is
 * here because the artifacts are part of the queue's contract, and the
 * add-frontend-panel skill uses it as the example of a list with
 * per-row actions.
 */
export function listArtifacts(jobId = '', limit = 50): Promise<Artifact[]> {
  return AppServiceBindings.ListArtifacts(jobId, limit) as unknown as Promise<Artifact[]>;
}

/**
 * Removes a stored artifact.
 *
 * No panel calls this yet: see listArtifacts.
 */
export function deleteArtifact(artifactId: string): Promise<void> {
  return AppServiceBindings.DeleteArtifact(artifactId) as Promise<void>;
}

/**
 * Returns the recorded debug console entries, oldest first.
 */
export function listConsoleEntries(): Promise<ConsoleEntry[]> {
  return AppServiceBindings.ListConsoleEntries() as unknown as Promise<ConsoleEntry[]>;
}

/**
 * Discards the recorded debug console entries.
 */
export function clearConsoleEntries(): Promise<void> {
  return AppServiceBindings.ClearConsoleEntries() as Promise<void>;
}

/**
 * Returns the application settings. The API key is never included.
 */
export function getSettings(): Promise<Settings> {
  return AppServiceBindings.GetSettings() as unknown as Promise<Settings>;
}

/**
 * Stores the API credentials. An empty apiKey keeps the stored key.
 */
export function saveCredentials(apiKey: string, baseUrl: string): Promise<void> {
  return AppServiceBindings.SaveCredentials(apiKey, baseUrl) as Promise<void>;
}

/**
 * Stores the interface preferences, including the zoom level.
 */
export function saveUI(ui: { zoom: number; theme: string }): Promise<void> {
  return AppServiceBindings.SaveUI(ui as never) as unknown as Promise<void>;
}

/**
 * Returns the imported Wikidata items the panel browses.
 *
 * The items are read by the backend from the database, where the
 * importer put them. An empty dataset is not an error: the panel shows
 * an empty list.
 */
export function getWikidataItems(limit: number, offset: number): Promise<WikidataItems> {
  return (
    AppServiceBindings.GetWikidataItems(limit, offset) as unknown as Promise<{
      items: WikidataModels.WikidataItemView[] | null;
      total: number | null;
      properties: Record<string, string> | null;
    }>
  ).then((view) => ({
    items: view.items ?? [],
    total: view.total ?? 0,
    properties: view.properties ?? {},
  }));
}

/**
 * A filter on the value of one property of an item.
 *
 * An item has no columns: its properties are claims, so a filter on a
 * property is a filter on a claim.
 */
export type WikidataClaimFilter = BindingsModels.WikidataClaimFilter;

/**
 * A request for one page of the items.
 *
 * The shape is the one the interface writes in, and it is translated to
 * the one the backend reads in `getWikidataItemsPage`: the generator
 * names the fields after the Go tags, which are the names of the wire
 * and not the names of the code.
 */
export interface WikidataPageRequest {
  readonly limit: number;
  readonly offset: number;
  readonly sortField: string;
  readonly sortDescending: boolean;
  readonly filters: readonly WikidataClaimFilter[];
}

/**
 * One page of the imported items.
 */
export type WikidataPage = {
  items: BindingsModels.WikidataItemView[];
  total: number;
  properties: Record<string, string>;
};

/**
 * Returns one page of the imported items.
 *
 * The filtering, the sorting and the counting happen in the database:
 * the gallery shows a dataset of a whole city, and reading all of it to
 * keep the twentieth part would not scale.
 */
export function getWikidataItemsPage(request: WikidataPageRequest): Promise<WikidataPage> {
  return (
    AppServiceBindings.GetWikidataItemsPage({
      limit: request.limit,
      offset: request.offset,
      sort_field: request.sortField,
      sort_descending: request.sortDescending,
      filters: request.filters.map((filter) => ({ property: filter.property, value: filter.value })),
    } as never) as unknown as Promise<{
      items: BindingsModels.WikidataItemView[] | null;
      total: number | null;
      properties: Record<string, string> | null;
    }>
  ).then((view) => ({
    items: view.items ?? [],
    total: view.total ?? 0,
    properties: view.properties ?? {},
  }));
}

/**
 * Returns the directory the datasets are read from.
 *
 * It is the data directory of the application, which is where the ETL
 * command leaves its output.
 */
export function getWikidataDataDir(): Promise<string> {
  return AppServiceBindings.GetWikidataDataDir() as unknown as Promise<string>;
}

/**
 * The progress of the last Wikidata import.
 */
export function getWikidataImportProgress(): Promise<WikidataPackage.ImportProgress> {
  return (
    AppServiceBindings.GetWikidataImportProgress() as unknown as Promise<WikidataPackage.ImportProgress>
  );
}

/**
 * Imports a Wikidata dataset into the database.
 *
 * The kind is 'items' or 'properties'. The import runs in the
 * background, and the progress is pushed to the frontend as a Wails
 * event.
 */
export function importWikidataFile(kind: string, path: string): Promise<void> {
  return AppServiceBindings.ImportWikidataFile(kind, path) as unknown as Promise<void>;
}

/**
 * Imports both datasets of a directory.
 */
export function importWikidataDirectory(path: string): Promise<void> {
  return AppServiceBindings.ImportWikidataDirectory(path) as unknown as Promise<void>;
}

/**
 * Stops the import that is running.
 */
export function cancelWikidataImport(): Promise<void> {
  return AppServiceBindings.CancelWikidataImport() as unknown as Promise<void>;
}

/**
 * Builds the shell pipeline that runs an ETL job.
 *
 * The command is the whole pipeline: the decompressor and the worker
 * of this same binary. It is what the interface shows, and what the
 * user copies to run the job in a terminal.
 */
export function buildEtlCommand(options: EtlJobOptions): Promise<string> {
  return AppServiceBindings.BuildEtlCommand(options as never) as unknown as Promise<string>;
}

/**
 * Runs an ETL job.
 *
 * The pipeline runs in the background, and the progress is pushed to
 * the frontend as a Wails event.
 */
export function startEtlJob(options: EtlJobOptions): Promise<EtlProgress> {
  return AppServiceBindings.StartEtlJob(options as never) as unknown as Promise<EtlProgress>;
}

/**
 * Stops a running ETL job.
 *
 * The whole process tree is stopped: the decompressor and the worker
 * die together.
 */
export function cancelEtlJob(runId: string): Promise<void> {
  return AppServiceBindings.CancelEtlJob(runId) as unknown as Promise<void>;
}

/**
 * Returns the runs of the ETL worker, the most recent first.
 */
export function listEtlHistory(limit: number): Promise<EtlHistoryEntry[]> {
  return (
    AppServiceBindings.ListEtlHistory(limit) as unknown as Promise<EtlHistoryEntry[] | null>
  ).then((entries) => entries ?? []);
}

/**
 * Removes a run from the ETL history.
 */
export function deleteEtlHistoryEntry(recordId: string): Promise<void> {
  return AppServiceBindings.DeleteEtlHistoryEntry(recordId) as unknown as Promise<void>;
}

/**
 * Returns the collections that can be synced and the configuration of
 * the sync.
 *
 * The password of the superuser is never returned: the backend only
 * ever says whether one is stored.
 */
export function getSyncSet(): Promise<SyncSet> {
  return (
    AppServiceBindings.GetSyncSet() as unknown as Promise<SyncSet & { collections: SyncCollection[] | null }>
  ).then((set) => ({ ...set, collections: set.collections ?? [] }));
}

/**
 * Stores the set of the collections that take part in a sync.
 */
export function saveSyncSet(set: SyncSet): Promise<void> {
  return AppServiceBindings.SaveSyncSet(set as never) as unknown as Promise<void>;
}

/**
 * Stores the password of the superuser of the remote server.
 *
 * The password is write-only from the point of view of the frontend:
 * it is stored encrypted and it is never sent back.
 */
export function setSyncPassword(password: string): Promise<void> {
  return AppServiceBindings.SetSyncPassword(password) as unknown as Promise<void>;
}

/**
 * Starts a sync of the whole set.
 *
 * The sync runs in the background, and the progress comes back as a
 * Wails event.
 */
export function startSync(): Promise<void> {
  return AppServiceBindings.StartSync() as unknown as Promise<void>;
}

/**
 * Stops the sync that is running.
 */
export function cancelSync(): Promise<void> {
  return AppServiceBindings.CancelSync() as unknown as Promise<void>;
}

/**
 * Returns the state of the last sync.
 */
export function getSyncProgress(): Promise<SyncProgress> {
  return AppServiceBindings.GetSyncProgress() as unknown as Promise<SyncProgress>;
}

/**
 * The generated model classes, re-exported for callers that need them.
 */
export { JobsModels, BindingsModels, ConsoleModels, WikidataModels, WikidataPackage };
